--5
INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Trem', 'thing/stuff', 'treng', 'Que trem é esse na sua mão?', 'Used for any object, tool, or food you can''t name right now.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Uai', 'huh?/I don''t get it/well/it is what it is', 'w-AHy', 'Ela tá brava porque perdeu? Mas eu joguei melhor, uai.', 'An expression of surprise or obviousness.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Bão', 'good', 'bown', 'Esse bolo de brigadeiro tá muito bão.', 'Short for "bom" — the standard Portuguese word for "good." Mineiros drop the formality.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Nó', 'wow/damn', 'naw', 'Nó, esse acidente de moto foi feio.', 'An expression of shock or disbelief — for good news, bad news, or pure gossip.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Bença', 'bless me', 'BENsah', 'Bença, vó Zena.', 'A request for blessing — common in families, especially in rural culture, as a sign of respect.', 2.5, 1, 0, date('now'));


--5
INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Muita raça de', 'a ton of', 'MWEENta HAssa gee', 'Tinha muita raça de gente no show do Dimas e Seus Teclados.', 'Slang for a surprisingly large crowd or quantity — like "a ton of". Structure: "muita raça de + [noun]', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Caçar', 'to look for (lit. "to hunt")', 'kahSSAR', 'Bryan não achou as chaves porque ele não caçou direito.', 'Informal, slightly humorous way to say "to look for" — but with a sense of active, intentional searching.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Dar uma geral', 'to tidy up/to sort out', 'dahr OONG-mah zheRAHL', 'Hoje de manhã, dei uma geral no meu quarto.', 'Informal way to say "tidy up" or "sort out" — for spaces or anything needing fixing.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Nem tchum', 'couldn''t care less', 'neng chuum', 'Eu avisei que ia chover, mas ele nem tchum.', 'Expression of total indifference — like "couldn''t care less" or "doesn''t bother me."', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Com Deus', 'God be with you', 'DEH-oos', 'Tchau, com Deus!', 'A warm, heartfelt farewell.', 2.5, 1, 0, date('now'));

--5
INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Ô', 'hey', 'aw', 'Ô mãe, cê viu meu chinelo?', 'Used to call someone''s attention casually — like "hey" in everyday speech.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Ligeiro', 'tell me about it/exactly/preach', 'leeZHEHro', '- Aquela cidade não é brincadeira. Tem que tomar cuidado. - Ligeiro.', 'Used to strongly agree with a heavy, uncomfortable, or eye-opening truth.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Bicho', 'buddy/man', 'BEEshoo', '- Eu fechei a porteira antes de passar as vaca. - Não bicho, tinha que ser ao contrário, uai.', 'A very countryside term for a close male friend — usually not used with strangers, only trusted company.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Bicho do mato', 'wallflower/hermit', 'BEEshoo doo MAHtoo', 'Por que que cê não gosta de ser filmado? Tá parecendo bicho do mato, uai.', 'A very countryside term for someone extremely shy who avoids attention and social situations.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Cê bobo', 'you''re silly/don''t be silly', 'seh BOHboo', 'Cê bobo. Não precisa dar essa volta toda de carro não. Tem um jeito mais fácil', 'Playful way to call someone silly or naive — also used to say "no way, you''re lying!"', 2.5, 1, 0, date('now'));

--5
INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Não ser chegado a...', 'not really into...', 'nown seh shehGAHdoo ah...', 'Não sou muito chegado em praia, não.', 'Used to say you''re not really into something — a mild, casual way to express disinterest.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Combinado!', 'Deal!', 'kombeeNAHdoo', '- Assim que eu sair te casa, eu te aviso, beleza? - Combinado!', 'A cheerful confirmation of an agreement — like "deal!" or "sounds good!"', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Zoando', 'joking around/messing with you', 'zuANdoo', 'Cê tá zoando ou cê tá falando sério?', 'Youthful slang for playfully joking around or messing with someone.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Misericórdia!', 'Good Lord!', 'meezehreeKORjah', '- Tem um escorpião dentro do banheiro! - Misericórdia!', 'Expression of shock or awe — like "Good Lord!" Can be genuine or playfully dramatic.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Ô de casa!', 'Hello? Anyone home?', 'aw jee KAHzah', 'Só depois que eu gritei "ôôô de casa", que ela me atendeu.', 'Traditional shout to announce your arrival at someone''s home — like "Hello? Anyone home?"', 2.5, 1, 0, date('now'));

--5
INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Alá', 'see?/look at that!', 'ahLAH', 'Alá, ele troca tanto de número de telefone que eu nunca sei.', 'Used to point something out — can express mild frustration, disbelief, or pure admiration.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Estar nela', 'to be out of it', 'stAR NEHlah', 'Ai.. que sono que eu tô nela.', 'Used to express being completely consumed by a feeling — like tiredness, hunger, or sleep.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Aiai...', 'oh boy../oh geez..', 'i-i', 'Aiai, kkkkk. Cês faz é graça.', 'A versatile sigh expressing irony, disbelief, amusement, or mild resignation — depending on tone.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Custando', 'barely', 'koosTAHnoo', 'Vó Zena tava custando subir as escadas.', 'Literally "costing" — used to mean "barely," when someone is struggling to do something.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Ser cismado', 'to be wary/to be particular', 'sehr seesMAHdoo', 'Tio Domingos é cismado e não gosta de receber muita visita não.', 'Being wary or particular — selective about people, situations, or habits, often due to distrust or strong boundaries.', 2.5, 1, 0, date('now'));

-- 5
INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Como diz o outro', 'as they say', 'KOHmoo jeez oo OHtroo', 'O café tava tão forte que, como diz o outro, levantava até defunto.', 'A phrase used to introduce a popular saying or common wisdom — like "as they say."', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Que nem', 'just like', 'kee neng', 'Ele fez que nem da última vez: disse que ia ajudar, e depois sumiu.', 'Informal way to say "just like" or "just as" — used for comparisons or references to past situations.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Cê tá doido', 'no way', 'seh tah DOYdoo', 'Cê tá doido, essa broa tá boa demais!', 'Literally "you''re crazy" — used for disbelief, shocked surprise, or to praise something impressive', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Cruz credo', 'God forbid', 'kroos KREHdoo', '- Ele diz que conversa com os mortos - Cruz credo!', 'A religious expression of repulsion or fear — like "God forbid!" Used to reject something disturbing.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Sua cara não queima não?', 'Aren''t you ashamed of yourself?', 'SOOah KAHrah now KAYmah now?', 'Joyce é a mais fofoqueira do time e agora tá se fazendo de vítima? A cara dela não queima não?', 'Used to call out someone who shows no shame for something they clearly should feel bad about.', 2.5, 1, 0, date('now'));


-- 5
INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Vergonha na cara', 'shame', 'vehrGONyah nah KAHrah', 'Esse homem precisa criar vergonha na cara dele.', 'Having basic shame, dignity, or moral decency about your own behavior and actions.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Rango', 'grub/food', 'HANgoo', 'O rango de hoje é frango com quiabo.', 'Informal slang for food or a meal — like "grub." "Chow" also works (it carries a military feel.)', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Pela cara', 'by the looks of it', 'PEHlah KAHrah', 'Pela cara, esse arroz carreteiro vai ficar muito bom.', 'Used to make a judgment based on appearance alone — like "by the looks of it."', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Filho de uma égua', 'son of a gun', 'FEElyoo jee OOmah EHgwah', 'O filho de uma égua não comeu nem um pedaço do bolo.', 'Literally "son of a mare" — used for frustration, admiration, or playful surprise depending on tone.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Pai', 'man', 'pah-ee', 'Olha o jeito que cê fala comigo, pai.', 'Casual way to address someone — like "man" or "buddy." More common in São Paulo.', 2.5, 1, 0, date('now'));


--5
INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Mina', 'Girl', 'MEEnah', 'Fiquei sabendo que o João Vitor tá saindo com uma mina da faculdade.', 'Casual slang for a girl or young woman — informal but not offensive.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Amigo da onça', 'Fair-weather friend', 'ahMEEgoo dah ONsah', 'Cuidado com a Cíntia que aquela ali é amiga da onça.', 'Literally "friend of the jaguar" — an unreliable person who may seem friendly but isn''t truly there for you.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Enxerido', 'nosy/busybody', 'ensheeREEdoo', 'Ana Laura é enxerida ao extremo. Acredita que ela perguntou se meu namorado dormiu na minha casa?', 'Someone who meddles in other people''s business or touches things that aren''t theirs.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Minha perna tá doce', 'my leg is jelly', 'MEEnyah PEHRnah tah DOHsee', 'Depois da trilha no Pico da Ibituruna, tava todo mundo com a perna doce.', 'Playful way to say your leg is completely worn out — like "my leg is jelly."', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Bom pra tosse', 'I''ll show them what''s what', 'bong prah TOHsee', 'Esse cliente acha que pode me tratar de qualquer jeito. Vou mostrar pra ele o que que é bom pra tosse.', 'Literally "good for a cough" — used to threaten showing someone a lesson or consequence.', 2.5, 1, 0, date('now'));


--5
INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Viu', 'okay?/alright?/got it?', 'veeoo', 'Não esquece de me avisar quando chegar, viu?', 'Soft tag added at the end of sentences to reinforce warmth, sincerity, emphasis, or expectation that the other person understood.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('O trem não é brincadeira', 'it''s no joke', 'oo treng now eh bringkahDAYrah', 'Eu sei que o trem não é brincadeira no seu trabalho.', 'Used when talking about a difficult, intense, stressful, or serious situation. Common for venting, empathy, or emphasizing that something is hard to deal with.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Novinha(o)', 'young hottie/cutie', 'noh-VEEN-yah(oo)', 'Conheci uma novinha lá no rock da Ana Júlia.', 'Slang for an attractive young person — usually someone people flirt with, hook up with, or show romantic interest in. Common in funk culture and casual youth speech.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Fiquei sabendo', 'I heard/I heard about it', 'feeKAY sahBENdoo', 'Fiquei sabendo que o Lázaro virou diretor de escola, uai.', 'Used when sharing news, gossip, rumors, or recent information you heard from someone else — like "I heard..." or "word is...".', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('O bicho tá pegando', 'things are getting rough', 'oo BEEshoo tah pehGANdoo', 'O bicho tá pegando lá em Cuba. A economia tá caindo demais.', 'Used when a situation is intense, chaotic, difficult, tense, or getting out of control — for personal drama, politics, money problems, fights, stress, etc.', 2.5, 1, 0, date('now'));


-- 5
INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Sugar a energia', 'to drain someone''s energy', 'sooGAR ah enehrZHEEah', 'A Laura suga todas as minhas energias quando ela começa a contar seus problemas emocionais.', 'Used for people, situations, or environments that emotionally exhaust you, mentally wear you down, or leave you feeling drained.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Como que tão as marés?', 'How''s everything going?', 'KOHmoo kee town ahs mahREHS', 'Marcelo Pereira! Cê sumiu. Como que tão as marés?', 'Relaxed, conversational way to ask how life is going or how things have been lately — similar to "How''s everything?" or "How are things?".', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Vamos embora que vem chuva!', 'We better get going', 'VAHmoos emBOHrah kee veng SHOOvah', 'É... vamos embora que vem chuva, né? Já tá ficando tarde também.', 'Playful, indirect way to say it''s time to leave someone''s house or end a visit. Often used jokingly instead of giving a direct goodbye.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('X anos nas costas', 'X years under your belt', 'ahnos nahs KOHStas', 'Antônio já tem mais de 30 anos nas costas e até hoje se comporta como uma criança.', 'Used to emphasize that someone is already old enough to know better, act mature, or take responsibility for their actions.', 2.5, 1, 0, date('now'));

INSERT INTO cards (word, translation, phonetic, example, explanation, easiness, interval, repetitions, next_review)
VALUES ('Cismar', 'to get fixated on/to get obsessed with', 'seezMAR', 'Não sei por quê, mas cismei com fazer academia.', 'Used when an idea, person, habit, or desire gets stuck in your head and you can''t stop thinking about it or wanting it.', 2.5, 1, 0, date('now'));
